import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { normalizeDueDate } from './public/task-due-date.js';

export function openProjectStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
    database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
    database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
  }
  const projectQuery = `SELECT id, name, archived, default_task_priority AS defaultTaskPriority,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id) AS totalCount,
    (SELECT COUNT(*) FROM tasks WHERE project_id = projects.id AND completed = 1) AS completedCount
    FROM projects`;
  const list = database.prepare(`${projectQuery} ORDER BY id`);
  const find = database.prepare(`${projectQuery} WHERE id = ?`);
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const updateName = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const updateDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
  const listTasks = database.prepare('SELECT id, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY id');
  const findTask = database.prepare('SELECT id, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const updateTaskTitle = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
  const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
  const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
  const taskRecord = (task) => task && { ...task, completed: Boolean(task.completed) };
  const projectRecord = (project) => project && { ...project, archived: Boolean(project.archived) };

  function requireActiveProject(projectId) {
    const project = find.get(projectId);
    if (!project || project.archived) {
      const error = new Error(project ? 'Archived projects cannot be changed' : 'Project not found');
      error.status = project ? 409 : 404;
      throw error;
    }
    return project;
  }

  return {
    list: () => list.all().map(projectRecord),
    find: (id) => projectRecord(find.get(id)),
    create(name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        throw new Error('Project name is required');
      }
      return projectRecord(find.get(insert.run(trimmedName).lastInsertRowid));
    },
    setArchived(id, archived) {
      if (typeof archived !== 'boolean') throw new Error('Project archive state must be a boolean');
      updateArchive.run(Number(archived), id);
      return projectRecord(find.get(id));
    },
    rename(id, name) {
      requireActiveProject(id);
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        const error = new Error('Project name is required');
        error.status = 400;
        throw error;
      }
      updateName.run(trimmedName, id);
      return projectRecord(find.get(id));
    },
    listTasks: (projectId) => listTasks.all(projectId).map(taskRecord),
    setDefaultTaskPriority(projectId, priority) {
      requireActiveProject(projectId);
      validatePriority(priority);
      updateDefaultTaskPriority.run(priority, projectId);
      return projectRecord(find.get(projectId));
    },
    createTask(projectId, title) {
      const project = requireActiveProject(projectId);
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) throw new Error('Task title is required');
      const result = insertTask.run(projectId, trimmedTitle, project.defaultTaskPriority);
      return taskRecord(findTask.get(projectId, result.lastInsertRowid));
    },
    setTaskCompletion(projectId, taskId, completed) {
      requireActiveProject(projectId);
      if (typeof completed !== 'boolean') throw new Error('Task completion must be a boolean');
      updateTask.run(Number(completed), projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    renameTask(projectId, taskId, title) {
      requireActiveProject(projectId);
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) {
        const error = new Error('Task title is required');
        error.status = 400;
        throw error;
      }
      updateTaskTitle.run(trimmedTitle, projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    setTaskPriority(projectId, taskId, priority) {
      requireActiveProject(projectId);
      validatePriority(priority);
      updateTaskPriority.run(priority, projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    setTaskDueDate(projectId, taskId, dueDate) {
      requireActiveProject(projectId);
      const normalized = normalizeDueDate(dueDate);
      updateTaskDueDate.run(normalized, projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    close: () => database.close(),
  };
}

function validatePriority(priority) {
  if (!['Low', 'Normal', 'High'].includes(priority)) {
    const error = new Error('Task priority must be Low, Normal, or High');
    error.status = 400;
    throw error;
  }
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjectStore } from './project-store.js';

const store = openProjectStore(process.env.DB_PATH || 'data/workboard.sqlite');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/task-filters.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-filters.js', import.meta.url))]],
  ['/task-due-date.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/task-due-date.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/styles.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (pathname === '/api/projects') {
      if (request.method === 'GET') return json(response, 200, store.list());
      if (request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.name !== 'string' || !input.name.trim()) {
          return json(response, 400, { error: 'Project name is required' });
        }
        return json(response, 201, store.create(input.name));
      }
    }
    const tasksApi = pathname.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
    if (tasksApi) {
      const [, projectId, taskId] = tasksApi;
      if (!store.find(projectId)) return json(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return json(response, 200, store.listTasks(projectId));
      }
      if (!taskId && request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.title !== 'string' || !input.title.trim()) {
          return json(response, 400, { error: 'Task title is required' });
        }
        return json(response, 201, store.createTask(projectId, input.title));
      }
      if (taskId && request.method === 'PATCH') {
        const input = await readJson(request);
        const fields = ['title', 'completed', 'priority', 'dueDate'].filter((field) => input && Object.hasOwn(input, field));
        if (fields.length > 1) {
          return json(response, 400, { error: 'Change task title, completion, priority, or due date separately' });
        }
        if (fields[0] === 'dueDate') {
          const task = store.setTaskDueDate(projectId, taskId, input.dueDate);
          return task
            ? json(response, 200, task)
            : json(response, 404, { error: 'Task not found' });
        }
        if (fields[0] === 'priority') {
          const task = store.setTaskPriority(projectId, taskId, input.priority);
          return task
            ? json(response, 200, task)
            : json(response, 404, { error: 'Task not found' });
        }
        if (input && Object.hasOwn(input, 'title')) {
          const task = store.renameTask(projectId, taskId, input.title);
          return task
            ? json(response, 200, task)
            : json(response, 404, { error: 'Task not found' });
        }
        if (typeof input?.completed !== 'boolean') {
          return json(response, 400, { error: 'Task completion must be a boolean' });
        }
        const task = store.setTaskCompletion(projectId, taskId, input.completed);
        return task
          ? json(response, 200, task)
          : json(response, 404, { error: 'Task not found' });
      }
    }
    const projectApi = pathname.match(/^\/api\/projects\/([1-9]\d*)$/);
    if (projectApi) {
      if (request.method === 'GET') {
        const project = store.find(projectApi[1]);
        return project
          ? json(response, 200, project)
          : json(response, 404, { error: 'Project not found' });
      }
      if (request.method === 'PATCH') {
        const input = await readJson(request);
        const fields = ['name', 'archived', 'defaultTaskPriority'].filter((field) => input && Object.hasOwn(input, field));
        if (fields.length > 1) {
          return json(response, 400, { error: 'Change project name, archive state, or default task priority separately' });
        }
        if (fields[0] === 'defaultTaskPriority') {
          return json(response, 200, store.setDefaultTaskPriority(projectApi[1], input.defaultTaskPriority));
        }
        if (input && Object.hasOwn(input, 'name')) {
          return json(response, 200, store.rename(projectApi[1], input.name));
        }
        if (typeof input?.archived !== 'boolean') {
          return json(response, 400, { error: 'Project archive state must be a boolean' });
        }
        const project = store.setArchived(projectApi[1], input.archived);
        return project
          ? json(response, 200, project)
          : json(response, 404, { error: 'Project not found' });
      }
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
